package dev.rodrigosambade.sockets;
import dev.rodrigosambade.net.ConnectivityAndInternetAccess;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.time.Duration;
public final class EchoClient{public static String echo(String host,int port,String message)throws IOException{ConnectivityAndInternetAccess.requireInternetForRemoteHost(host,Duration.ofSeconds(2));try(Socket s=new Socket()){s.connect(new InetSocketAddress(host,port),3000);s.setSoTimeout(3000);try(var in=new BufferedReader(new InputStreamReader(s.getInputStream(),StandardCharsets.UTF_8));var out=new BufferedWriter(new OutputStreamWriter(s.getOutputStream(),StandardCharsets.UTF_8))){out.write(message);out.newLine();out.flush();return in.readLine();}}}public static void main(String[]a)throws Exception{if(a.length<3)throw new IllegalArgumentException("host port message");System.out.println(echo(a[0],Integer.parseInt(a[1]),a[2]));}}
